update public.activities as activities
set
  google_place_id = coalesce(image_updates.google_place_id, activities.google_place_id),
  google_place_uri = coalesce(image_updates.google_place_uri, activities.google_place_uri),
  google_photo_url = coalesce(image_updates.google_photo_url, activities.google_photo_url),
  google_rating = coalesce(image_updates.google_rating, activities.google_rating),
  google_user_rating_count = coalesce(image_updates.google_user_rating_count, activities.google_user_rating_count),
  scraped_image_url = coalesce(image_updates.scraped_image_url, activities.scraped_image_url),
  website_image_url = coalesce(image_updates.website_image_url, activities.website_image_url),
  listing_image_url = coalesce(image_updates.listing_image_url, activities.listing_image_url),
  image_url = coalesce(image_updates.image_url, activities.image_url),
  image_source_url = coalesce(image_updates.image_source_url, activities.image_source_url),
  updated_at = now()
from image_updates
where activities.activity_id = image_updates.activity_id;

